await window.DockProjectSync?.ready;const $=id=>document.getElementById(id),profile=window.DockMember||{};
const welcome=$('jane-welcome');let timer;function hideWelcome(){clearTimeout(timer);if(welcome)welcome.hidden=true}function showWelcome(){if(!welcome)return;welcome.hidden=false;timer=setTimeout(hideWelcome,matchMedia('(prefers-reduced-motion:reduce)').matches?500:2200)}if(welcome){$('welcome-skip').onclick=hideWelcome;showWelcome()}
if($('jane-settings')){$('jane-settings').onclick=()=>$('jane-settings-dialog').showModal();$('jane-settings-close').onclick=()=>$('jane-settings-dialog').close();$('jane-theme').onclick=()=>DockAppearance.toggleTheme();$('welcome-again').onclick=()=>{$('jane-settings-dialog').close();showWelcome()}}
if(profile.preview){if($('preview-banner'))$('preview-banner').hidden=false;if($('member-preview-note'))$('member-preview-note').hidden=false;if($('preview-exit-label'))$('preview-exit-label').hidden=false;if($('preview-exit'))$('preview-exit').onchange=async event=>{const toggle=event.target;toggle.disabled=true;try{await profile.exitPreview()}catch{toggle.checked=true;toggle.disabled=false;$('preview-error').textContent='Could not leave preview. Retry when signed in.'}}}
async function account(data,method='POST'){const response=await fetch('/api/groupme-account',{method:data?method:'GET',credentials:'same-origin',cache:'no-store',...(data?{headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const result=await response.json();if(!response.ok)throw Error(result.error||'Connection unavailable.');return result}
function render(result){$('account-state').textContent=result.connected?'Connected as '+result.account.name+'. This is your GroupMe account.':'Your own GroupMe account isn’t connected yet.';$('open-groupme').hidden=!result.connected;$('disconnect-account').hidden=!result.connected;$('member-connect').hidden=result.connected}
if($('member-connect')){try{render(await account())}catch(error){$('account-state').textContent=error.message}$('member-connect').onsubmit=async event=>{event.preventDefault();$('connect-account').disabled=true;let token=$('groupme-token').value;$('groupme-token').value='';try{render(await account({token}))}catch(error){$('account-state').textContent=error.message}finally{token='';$('connect-account').disabled=false}};$('disconnect-account').onclick=async()=>{$('disconnect-account').disabled=true;try{render(await account({},'DELETE'))}catch(error){$('account-state').textContent=error.message}finally{$('disconnect-account').disabled=false}}}
